setupCode:
@use '@angular/material' as mat;

html {
  @include mat.theme((
    color: mat.$violet-palette,
    typography: (
      plain-family: 'Inter, sans-serif',
      brand-family: 'Inter, sans-serif',
      bold-weight: 700,
      medium-weight: 500,
      regular-weight: 400,
    ),
    density: 0,
  ));
}

body {
  // Google Fonts (or a self-hosted equivalent) must be loaded separately —
  // mat.theme only emits CSS custom properties, not a @font-face or <link>.
  font-family: 'Inter', sans-serif;
}
